WITH src AS (SELECT *, DATE_FORMAT(sale_date, 'yyyy-MM') AS sale_date_label FROM store_sales WHERE revenue >= 1600 AND (revenue >= 3100 OR revenue BETWEEN 2400 AND 2900)), summary AS (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, store_id, MAX(units) AS max_units, ROUND(AVG(revenue), 2) AS avg_revenue FROM src GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END, store_id) SELECT * FROM summary WHERE avg_revenue < 54
